27	
28	#include <riscv_vector.h>
29	#include <stdint.h>
30	#include <stdio.h>
31	
32	#define N 16
33	
34	/* Repeat count for the vsim-phase kernel. The marked build (default,
35	 * GEMM_REPEAT=1) runs the GEMM once between the drain markers, behavior-
36	 * identical to a single matmul. The markerless twin (built with
37	 * -DHYBRID_MARKERLESS -DGEMM_REPEAT=K) drops the markers and runs K back-to-
38	 * back GEMMs, lengthening the instruction stream so the count-driven modes
39	 * (icount / bbv / slice) have a long, marker-free window to sample. Each
40	 * kernel call re-seeds its accumulator and overwrites C, so repeating is
41	 * idempotent -- the phase-3 scalar verify holds for any GEMM_REPEAT >= 1. */
42	#ifndef GEMM_REPEAT
43	#define GEMM_REPEAT 1
44	#endif
45	
46	static int32_t A[N * N];
47	static int32_t B[N * N];
48	static int32_t C[N * N];
49	
50	#define AT(M, i, j) ((M)[(i) *N + (j)])
51	
52	/* Vectorized init: one V register holds [0, 1, ..., N-1], reused across
53	 * rows. Per row i: A[i][:] = (vidx + i)   % 7, B[i][:] = (vidx + 3i) % 5.
54	 * vid.v writes unsigned lane indices; reinterpret to signed so the rest of
55	 * the math (and the int32_t* matrix pointers) stay in i32 land. */
