57	{
58	  size_t           vl     = __riscv_vsetvl_e32m1((size_t) N);
59	  const vuint32m1_t vidx_u = __riscv_vid_v_u32m1(vl);
60	  const vint32m1_t  vidx   = __riscv_vreinterpret_v_u32m1_i32m1(vidx_u);
61	
62	  for (int i = 0; i < N; i++) {
63	    vint32m1_t va = __riscv_vadd_vx_i32m1(vidx, i, vl);
64	    va            = __riscv_vrem_vx_i32m1(va, 7, vl);
65	    __riscv_vse32_v_i32m1(&AT(A, i, 0), va, vl);
66	
67	    vint32m1_t vb = __riscv_vadd_vx_i32m1(vidx, i * 3, vl);
68	    vb            = __riscv_vrem_vx_i32m1(vb, 5, vl);
69	    __riscv_vse32_v_i32m1(&AT(B, i, 0), vb, vl);
70	  }
71	}
72	
73	/* Outer-product RVV GEMM: for each row i of C, accumulate
74	 *   C[i][:] += A[i][k] * B[k][:]
75	 * using a single V register per row.
76	 *
77	 * noinline keeps the kernel a distinct symbol at -O1 so PC-range modes can
78	 * anchor on it, and keeps every kernel op inside the marker span (a call
79	 * cannot be reordered across the memory-clobbering enter/exit markers; see
80	 * runtime/rt_c_helpers.h cycle-attribution contract). */
81	static void __attribute__((noinline)) vmatmul_kernel(void)
82	{
83	  for (int i = 0; i < N; i++) {
84	    size_t     vl   = __riscv_vsetvl_e32m1((size_t) N);
85	    vint32m1_t vacc = __riscv_vmv_v_x_i32m1(0, vl);
86	    for (int k = 0; k < N; k++) {
87	      const int32_t  a_ik = AT(A, i, k);
88	      const vint32m1_t vb_k =
89	        __riscv_vle32_v_i32m1(&AT(B, k, 0), vl);
90	      vacc = __riscv_vmacc_vx_i32m1(vacc, a_ik, vb_k, vl);
91	    }
92	    __riscv_vse32_v_i32m1(&AT(C, i, 0), vacc, vl);
93	  }
94	}
95	
96	/* Pure scalar reference, independent of the RVV kernel above. */
97	static int scalar_matmul_verify(void)
98	{
